// QR encoder of the till stickers (M4): same symbol as a reference encoder (Dart package qr,
// byte mode, level M), for a forced mask; any mask decodes, the best one is chosen by penalty.
import { describe, expect, it } from 'vitest';
import { qrMatrix } from '../../src/common/qr.js';
import { stickerPdf } from '../../src/common/sticker-pdf.js';

const LINK = 'https://pay.flexipay.tn/c/Ab3dEf5hIj7kLm9nOp1qRs?s=Tu2vWx4yZa6bCd8eFg0hIj';
/** Modules of the reference symbol (mask 3), row by row, 1 = dark. */
const REFERENCE_MASK_3 =
  '';

describe('qrMatrix', () => {
  it('matches the reference encoder module for module', () => {
    const matrix = qrMatrix(LINK, 3);
    expect(matrix.length).toBe(37);
    expect(matrix.map((row) => row.map((dark) => (dark ? '1' : '0')).join('')).join('')).toBe(
      REFERENCE_MASK_3,
    );
  });

  it('chooses a version that fits and refuses a text too long', () => {
    expect(qrMatrix('flexipay').length).toBe(21);
    expect(() => qrMatrix('x'.repeat(400))).toThrow('qr: text too long');
  });
});

describe('stickerPdf', () => {
  it('is an 8 × 8 cm PDF page with the names and the instruction', () => {
    const pdf = stickerPdf({
      merchantName: 'Carrefour',
      registerName: 'Caisse 1',
      url: LINK,
      instruction: ['Payez avec FlexiPay :', 'approchez votre téléphone ou scannez'],
    }).toString('latin1');
    expect(pdf.startsWith('%PDF-1.4')).toBe(true);
    expect(pdf).toContain('/MediaBox [0 0 226.77 226.77]');
    expect(pdf).toContain('(Carrefour)');
    expect(pdf).toContain('(Caisse 1)');
    expect(pdf).toContain('(approchez votre t\xe9l\xe9phone ou scannez)');
    expect(pdf.trimEnd().endsWith('%%EOF')).toBe(true);
  });
});
